fn project_path(dir: &str, rel: &str) -> Result<PathBuf, String> {
    let base = PathBuf::from(dir);
    if !base.is_dir() {
        return Err("Pasta do projeto não encontrada.".into());
    }
    let rel_path = Path::new(rel);
    if rel.is_empty() || rel_path.is_absolute() || rel_path.components().any(|c| !matches!(c, Component::Normal(_))) {
        return Err(format!("Caminho inválido: {rel}"));
    }
    let target = base.join(rel_path);

    // CRITICAL: Resolve symlinks and verify containment
    let canonical_base = fs::canonicalize(&base).map_err(|e| format!("Falha ao resolver caminho base: {e}"))?;
    let canonical_target = fs::canonicalize(&target).map_err(|e| format!("Falha ao resolver caminho alvo: {e}"))?;

    if !canonical_target.starts_with(&canonical_base) {
        return Err(format!("Caminho fora do projeto: {rel}"));
    }

    Ok(target)
}

fn validate_not_symlink(path: &Path) -> Result<(), String> {
    let meta = fs::metadata(path).map_err(|e| format!("Falha ao verificar metadados: {e}"))?;
    if meta.file_type().is_symlink() {
        return Err("Caminho é um link simbólico - operação negada".into());
    }
    #[cfg(windows)]
    {
        // Check for junction points / reparse points on Windows
        use std::os::windows::fs::MetadataExt;
        if meta.file_attributes() & 0x400 != 0 { // FILE_ATTRIBUTE_REPARSE_POINT
            return Err("Caminho é um ponto de reanálise (junction) - operação negada".into());
        }
    }
    Ok(())
}

